pub fn emit_data_value_json(value: Rc<Node>, source_index: Option<Rc<NewlineIndex>>) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*value.expr_data.clone()).clone() {
    ExprData::ExprLiteral { value: v, .. } => match (*v.clone()).clone() {
    LiteralValue::LitStr { value: s, .. } => v2_rt::concat(v2_rt::concat("\"".to_string(), escape_json_string(s.clone())), "\"".to_string()),
    LiteralValue::LitInt { value: i, .. } => (i.clone()).to_string(),
    LiteralValue::LitFloat { value: f, .. } => f.clone(),
    LiteralValue::LitBool { value: b, .. } => if b.clone() {
            "true".to_string()
} else {
            "false".to_string()
},
    LiteralValue::LitNull => "null".to_string(),
},
    ExprData::ExprListLit => {
            let el_strs = Rc::new({ let mut __result = Vec::new(); for e in value.children.clone().iter().cloned() { __result.push(emit_data_value_json(e.clone(), source_index.clone())); } __result });
v2_rt::concat(v2_rt::concat("[".to_string(), el_strs.join(&", ".to_string())), "]".to_string())
},
    ExprData::ExprRecordLit { .. } => {
            let field_strs = Rc::new({ let mut __result = Vec::new(); for f in value.children.clone().iter().cloned() { __result.push(v2_rt::concat(v2_rt::concat(v2_rt::concat("\"".to_string(), escape_json_string(field_init_node_name(f.clone()))), "\": ".to_string()), emit_data_value_json(field_init_node_value(f.clone()), source_index.clone()))); } __result });
v2_rt::concat(v2_rt::concat("{".to_string(), field_strs.join(&", ".to_string())), "}".to_string())
},
    ExprData::ExprVar { .. } => v2_rt::concat(v2_rt::concat("\"".to_string(), escape_json_string(expr_var_name_at(value.clone(), source_index.clone()))), "\"".to_string()),
    ExprData::ExprUnaryOp { op: UnaryOpKind::Neg, .. } => v2_rt::concat("-".to_string(), emit_data_value_json(unaryop_operand(value.clone()), source_index.clone())),
    _ => "\"compile_error!(unsupported mock expression)\"".to_string(),
}
    })
}

pub fn escape_json_string(s: String) -> String {
    Rc::new(Rc::new(Rc::new(Rc::new(s.split(&"\\".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"\\\\".to_string()).split(&"\"".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"\\\"".to_string()).split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"\\n".to_string()).split(&"\t".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"\\t".to_string())
}

pub fn module_to_filename(name: String) -> String {
    Rc::new(name.split(&".".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"_".to_string())
}

pub fn make_indent(level: i64) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if (level.clone() <= 0) {
            "".to_string()
} else {
            v2_rt::concat("    ".to_string(), make_indent((level.clone() - 1)))
}
    })
}

pub fn to_string(value: i64) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if (value.clone() < 0) {
            v2_rt::concat("-".to_string(), ((0 - value.clone())).to_string())
} else {
            if (value.clone() == 0) {
                "0".to_string()
} else {
                {
                    let digit_chars = Rc::new(vec!["0".to_string(), "1".to_string(), "2".to_string(), "3".to_string(), "4".to_string(), "5".to_string(), "6".to_string(), "7".to_string(), "8".to_string(), "9".to_string()]);
to_string_helper(value.clone(), Rc::new(vec![])).join(&"".to_string())
}
}
}
    })
}

pub fn to_string_helper(mut value: i64, mut acc: Rc<Vec<String>>) -> Rc<Vec<String>> {
    loop {
        if (value.clone() == 0) {
            break acc.clone();
} else {
            let digit = (value.clone() % 10);
let rest = ((value.clone() - digit.clone()) / 10);
let digit_chars = Rc::new(vec!["0".to_string(), "1".to_string(), "2".to_string(), "3".to_string(), "4".to_string(), "5".to_string(), "6".to_string(), "7".to_string(), "8".to_string(), "9".to_string()]);
let ch = match Rc::new({ let mut __result = Vec::new(); for p in Rc::new(digit_chars.clone().iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect::<Vec<_>>()).iter().cloned() { if (p.0.clone() == digit.clone()) { __result.push(p); } } __result }).first().cloned() {
    Some(p) => p.1.clone(),
    None => "?".to_string(),
};
{
                let __tco_0 = rest.clone();
let __tco_1 = v2_rt::concat(Rc::new(vec![ch.clone()]), acc);
value = __tco_0;
acc = __tco_1;
continue;
}
}
}
}

pub fn to_snake(name: String) -> String {
    {
        let chars_list = Rc::new(name.chars().map(|c| c as i64).collect::<Vec<_>>());
let result = Rc::new({ let mut __result = Vec::new(); for pair in Rc::new(chars_list.iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect::<Vec<_>>()).iter().cloned() { __result.push({
            let idx = pair.0.clone();
let ch = pair.1.clone();
if is_upper(ch.clone()) {
                if (idx.clone() == 0) {
                    to_lower_char(ch.clone())
} else {
                    v2_rt::concat("_".to_string(), to_lower_char(ch.clone()))
}
} else {
                v2_rt::from_code_point(ch.clone())
}
}); } __result });
result.join(&"".to_string())
}
}

pub fn to_screaming_snake(name: String) -> String {
    {
        let snake = to_snake(name);
Rc::new({ let mut __result = Vec::new(); for ch in Rc::new(snake.chars().map(|c| c as i64).collect::<Vec<_>>()).iter().cloned() { __result.push(to_upper_char(ch.clone())); } __result }).join(&"".to_string())
}
}

pub fn is_upper(ch: i64) -> bool {
    ((ch.clone() >= 65) && (ch.clone() <= 90))
}

pub fn to_lower_char(ch: i64) -> String {
    {
        let cp = ch.clone();
if ((cp.clone() >= 65) && (cp.clone() <= 90)) {
            {
                let lower_cp = (cp.clone() + 32);
v2_rt::from_code_point(lower_cp)
}
} else {
            v2_rt::from_code_point(ch.clone())
}
}
}

pub fn to_upper_char(ch: i64) -> String {
    {
        let cp = ch.clone();
if ((cp.clone() >= 97) && (cp.clone() <= 122)) {
            {
                let upper_cp = (cp.clone() - 32);
v2_rt::from_code_point(upper_cp)
}
} else {
            v2_rt::from_code_point(ch.clone())
}
}
}

pub fn sanitize_service_name(name: String) -> String {
    {
        let parts = Rc::new(name.split(&".".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
let pascal_parts = Rc::new({ let mut __result = Vec::new(); for p in parts.iter().cloned() { __result.push(capitalize_first(p.clone())); } __result });
pascal_parts.join(&"".to_string())
}
}

pub fn capitalize_first(s: String) -> String {
    {
        let chars_list = Rc::new(s.chars().map(|c| c as i64).collect::<Vec<_>>());
if ((chars_list.clone().len() as i64) == 0) {
            "".to_string()
} else {
            Rc::new({ let mut __result = Vec::new(); for pair in Rc::new(chars_list.clone().iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect::<Vec<_>>()).iter().cloned() { __result.push(if (pair.0.clone() == 0) {
                to_upper_char(pair.1.clone())
} else {
                v2_rt::from_code_point(pair.1.clone())
}); } __result }).join(&"".to_string())
}
}
}

pub fn to_pascal(name: String) -> String {
    {
        let snake = to_snake(name);
let parts = Rc::new(snake.split(&"_".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
let pascal_parts = Rc::new({ let mut __result = Vec::new(); for p in parts.iter().cloned() { __result.push(capitalize_first(p.clone())); } __result });
pascal_parts.join(&"".to_string())
}
}

pub fn service_var_name(service_name: String) -> String {
    to_snake(sanitize_service_name(service_name))
}

pub fn test_function_name(projection: Rc<TestProjection>, target: RenderTarget) -> String {
    {
        let conventions = test_conventions_for_target(target);
let formatted = match conventions.name_style.clone() {
    TestNameStyle::SnakeCaseTestNames => v2_rt::concat(v2_rt::concat(to_snake(sanitize_service_name(projection.service_name.clone())), "_".to_string()), to_snake(projection.operation_name.clone())),
    TestNameStyle::PascalCaseTestNames => v2_rt::concat(to_pascal(sanitize_service_name(projection.service_name.clone())), to_pascal(projection.operation_name.clone())),
};
v2_rt::concat(conventions.function_prefix.clone(), formatted)
}
}

pub fn apply_type_template1(template: String, arg0: String) -> String {
    Rc::new(template.split(&"{0}".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&arg0)
}

pub fn apply_type_template2(template: String, arg0: String, arg1: String) -> String {
    {
        let parts = Rc::new(template.split(&"{0}".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
let replaced = Rc::new({ let mut __result = Vec::new(); for p in parts.iter().cloned() { __result.push(Rc::new(p.clone().split(&"{1}".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&arg1.clone())); } __result });
replaced.join(&arg0)
}
}

pub fn apply_type_template3(template: String, arg0: String, arg1: String, arg2: String) -> String {
    {
        let parts0 = Rc::new(template.split(&"{0}".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
let replaced = Rc::new({ let mut __result = Vec::new(); for p0 in parts0.iter().cloned() { __result.push({
            let parts1 = Rc::new(p0.clone().split(&"{1}".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
let inner = Rc::new({ let mut __result = Vec::new(); for p1 in parts1.clone().iter().cloned() { __result.push(Rc::new(p1.clone().split(&"{2}".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&arg2.clone())); } __result });
inner.clone().join(&arg1.clone())
}); } __result });
replaced.join(&arg0)
}
}

pub fn apply_named_template(template: String, bindings: Rc<HashMap<String, String>>) -> String {
    apply_named_template_nested(template, bindings.clone(), Rc::new(v2_rt::map_keys(&bindings)))
}

pub fn apply_named_template_nested(template: String, bindings: Rc<HashMap<String, String>>, keys: Rc<Vec<String>>) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match keys.clone().first().cloned() {
    None => template,
    Some(key) => {
            let rest = Rc::new(keys.clone().iter().cloned().skip(1 as usize).collect::<Vec<_>>());
let placeholder = v2_rt::concat(v2_rt::concat("{".to_string(), key.clone()), "}".to_string());
match v2_rt::map_get(&bindings, key.clone()) {
    Some(val) => {
                let parts = Rc::new(template.split(&placeholder).map(|s| s.to_string()).collect::<Vec<_>>());
let processed = Rc::new({ let mut __result = Vec::new(); for part in parts.iter().cloned() { __result.push(apply_named_template_nested(part.clone(), bindings.clone(), rest.clone())); } __result });
processed.join(&val.clone())
},
    None => v2_rt::concat("TEMPLATE_ERROR_MISSING_BINDING_".to_string(), key.clone()),
}
},
}
    })
}

pub fn language_spec(target: RenderTarget) -> Rc<LanguageSpec> {
    language_spec_for_target(target)
}

pub fn reserved_prefix(target: RenderTarget) -> String {
    match (*language_spec(target).reserved_words.clone().strategy.clone()).clone() {
    ReservedWordStrategy::PrefixEscape { prefix, .. } => prefix.clone(),
    _ => "".to_string(),
}
}

pub fn reserved_suffix(target: RenderTarget) -> String {
    match (*language_spec(target).reserved_words.clone().strategy.clone()).clone() {
    ReservedWordStrategy::SuffixEscape { suffix, .. } => suffix.clone(),
    _ => "".to_string(),
}
}

pub fn escape_string_literal_body(s: String) -> String {
    {
        let escaped_backslash = Rc::new(s.split(&"\\".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"\\\\".to_string());
let escaped_quote = Rc::new(escaped_backslash.split(&"\"".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"\\\"".to_string());
let escaped_newline = Rc::new(escaped_quote.split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"\\n".to_string());
let escaped_return = Rc::new(escaped_newline.split(&"\\r".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"\\r".to_string());
Rc::new(escaped_return.split(&"\t".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"\\t".to_string())
}
}

pub fn escape_rust_interp_text(s: String) -> String {
    {
        let escaped = Rc::new(escape_string_literal_body(s).split(&"{".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"{{".to_string());
Rc::new(escaped.split(&"}".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"}}".to_string())
}
}

pub fn escape_go_interp_text(s: String) -> String {
    Rc::new(escape_string_literal_body(s).split(&"%".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"%%".to_string())
}

pub fn escape_python_interp_text(s: String) -> String {
    {
        let escaped = Rc::new(escape_string_literal_body(s).split(&"{".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"{{".to_string());
Rc::new(escaped.split(&"}".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).join(&"}}".to_string())
}
}

pub fn emit_string_literal(s: String, suffix: String) -> String {
    v2_rt::concat(v2_rt::concat(v2_rt::concat("\"".to_string(), escape_string_literal_body(s)), "\"".to_string()), suffix)
}

pub fn is_null_coalesce(op: BinOp) -> bool {
    match op {
    BinOp::NullCoalesce => true,
    _ => false,
}
}

pub fn rust_literal_for_pattern(value: Rc<LiteralValue>) -> String {
    match (*value).clone() {
    LiteralValue::LitStr { value: s, .. } => emit_string_literal(s.clone(), "".to_string()),
    LiteralValue::LitInt { value: i, .. } => (i.clone()).to_string(),
    LiteralValue::LitFloat { value: f, .. } => f.clone(),
    LiteralValue::LitBool { value: b, .. } => if b.clone() {
        emit_keyword("true".to_string(), RenderTarget::Rust)
} else {
        emit_keyword("false".to_string(), RenderTarget::Rust)
},
    LiteralValue::LitNull => emit_keyword("null".to_string(), RenderTarget::Rust),
}
}

pub fn emit_keyword(key: String, target: RenderTarget) -> String {
    target_keyword(target, key)
}

pub fn emit_literal(value: Rc<LiteralValue>, target: RenderTarget) -> String {
    match (*value).clone() {
    LiteralValue::LitStr { value: s, .. } => {
        let suffix = match target {
    RenderTarget::Rust => ".to_string()".to_string(),
    _ => "".to_string(),
};
emit_string_literal(s.clone(), suffix)
},
    LiteralValue::LitInt { value: i, .. } => (i.clone()).to_string(),
    LiteralValue::LitFloat { value: f, .. } => f.clone(),
    LiteralValue::LitBool { value: b, .. } => if b.clone() {
        emit_keyword("true".to_string(), target)
} else {
        emit_keyword("false".to_string(), target)
},
    LiteralValue::LitNull => emit_keyword("null".to_string(), target),
}
}

pub fn emit_bin_op_symbol(op: BinOp, target: RenderTarget) -> String {
    match op {
    BinOp::Add => "+".to_string(),
    BinOp::Sub => "-".to_string(),
    BinOp::Mul => "*".to_string(),
    BinOp::Div => emit_keyword("div".to_string(), target),
    BinOp::Mod => "%".to_string(),
    BinOp::Eq => "==".to_string(),
    BinOp::Ne => "!=".to_string(),
    BinOp::Lt => "<".to_string(),
    BinOp::Gt => ">".to_string(),
    BinOp::Le => "<=".to_string(),
    BinOp::Ge => ">=".to_string(),
    BinOp::And => emit_keyword("and".to_string(), target),
    BinOp::Or => emit_keyword("or".to_string(), target),
    BinOp::NullCoalesce => "??".to_string(),
}
}

pub fn emit_container(kind: String, inner: String, target: RenderTarget) -> String {
    if (kind.clone().as_str() == "optional".to_string().as_str()) {
        apply_type_template1(target_optional_template(target.clone()), inner)
} else {
        match coerce_container_template(target.clone(), kind.clone()) {
    Some(template) => apply_type_template1(template.clone(), inner),
    None => match target.clone() {
    RenderTarget::Python => v2_rt::concat(v2_rt::concat(v2_rt::concat(kind.clone(), "[".to_string()), inner), "]".to_string()),
    _ => v2_rt::concat(v2_rt::concat(v2_rt::concat(kind.clone(), "<".to_string()), inner), ">".to_string()),
},
}
}
}

pub fn emit_map_type(key_type: String, val_type: String, target: RenderTarget) -> String {
    match coerce_container_template(target, "map".to_string()) {
    Some(template) => apply_type_template2(template.clone(), key_type, val_type),
    None => v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("Map<".to_string(), key_type), ", ".to_string()), val_type), ">".to_string()),
}
}

pub fn emit_node_type(n: Rc<Node>, target: RenderTarget, source_index: Option<Rc<NewlineIndex>>) -> String {
    render_node_type(n, target, v2_rt::rc_empty_map::<bool>(), source_index)
}

pub fn render_node_type(n: Rc<Node>, target: RenderTarget, shared_types: Rc<HashMap<String, bool>>, source_index: Option<Rc<NewlineIndex>>) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        {
            let n_is_error = if (n.inferred.clone() != None) {
                is_compiler_error(n.inferred.clone().clone().unwrap())
} else {
                false
};
let n_is_type_var = if (n.inferred.clone() != None) {
                is_type_variable(n.inferred.clone().clone().unwrap())
} else {
                false
};
if ((n_is_type_var || n_is_error.clone()) && ((n.children.clone().len() as i64) == 0)) {
                {
                    let label = if n_is_error.clone() {
                        "CompilerError".to_string()
} else {
                        "TypeVariable".to_string()
};
let err_str = match target.clone() {
    RenderTarget::Rust => v2_rt::concat(v2_rt::concat("compile_error!(\"unresolved ".to_string(), label), " type reached emit\")".to_string()),
    _ => v2_rt::concat(v2_rt::concat("__EMIT_BUG_UNRESOLVED_".to_string(), label), "__".to_string()),
};
return err_str
}
}
let is_arrow = (n.connective.clone() == Connective::Arrow);
if is_arrow {
                {
                    let repr = target_callable(target.clone());
let param_strs = Rc::new({ let mut __result = Vec::new(); for p in n.params.clone().iter().cloned() { __result.push(render_node_type(param_node_type_expr(p.clone()), target.clone(), shared_types.clone(), source_index.clone())); } __result });
let param_str = param_strs.join(&repr.param_separator.clone());
let ret_str = match n.inferred.clone().as_deref().cloned() {
    Some(InferredNode::Resolved { node: rt, .. }) => render_node_type(rt.clone(), target.clone(), shared_types.clone(), source_index.clone()),
    _ => match target.clone() {
    RenderTarget::Go => "".to_string(),
    RenderTarget::Python => "None".to_string(),
    _ => "()".to_string(),
},
};
let callable_str = v2_rt::replace(v2_rt::replace(repr.template.clone(), "{params}".to_string(), param_str.clone()), "{return}".to_string(), ret_str.clone());
let go_callable_str = if (ret_str.clone().as_str() == "".to_string().as_str()) {
                        v2_rt::concat(v2_rt::concat("func(".to_string(), param_str.clone()), ")".to_string())
} else {
                        callable_str.clone()
};
let result = match target.clone() {
    RenderTarget::Rust => v2_rt::concat(v2_rt::concat("Rc<dyn ".to_string(), v2_rt::replace(callable_str.clone(), "fn(".to_string(), "Fn(".to_string())), ">".to_string()),
    RenderTarget::Go => go_callable_str,
    _ => callable_str.clone(),
};
return result
}
}
let is_optional = (n.return_cardinality.clone() == Cardinality::CardOptional);
if is_optional {
                {
                    let inner_str = render_node_type(with_required_cardinality(n.clone()), target.clone(), shared_types.clone(), source_index.clone());
let opt_str = emit_container("optional".to_string(), inner_str, target.clone());
return opt_str
}
}
let is_conj = (n.connective.clone() == Connective::Conj);
let is_disj = (n.connective.clone() == Connective::Disj);
let shared = emit_map_has(shared_types.clone(), n.name.clone());
if is_disj {
                {
                    let base = if (n.ident_span.clone() != None) {
                        coerce_primitive_type(target.clone(), n.name.clone())
} else {
                        match target.clone() {
    RenderTarget::Rust => "compile_error!(\"unresolved anonymous coproduct type reached emit\")".to_string(),
    _ => "__EMIT_BUG_ANONYMOUS_COPRODUCT__".to_string(),
}
};
let disj_str = if shared.clone() {
                        wrap_shared_type(target.clone(), base.clone())
} else {
                        base.clone()
};
return disj_str
}
}
if is_conj {
                {
                    if (n.type_annotation.clone() != None) {
                        {
                            let refined_str = match n.children.clone().first().cloned() {
    Some(base) => render_node_type(base.clone(), target.clone(), shared_types.clone(), source_index.clone()),
    None => coerce_primitive_type(target.clone(), "Refined".to_string()),
};
return refined_str
}
}
let is_pair = (((n.children.clone().len() as i64) == 2) && { let mut __all = true; for c in n.children.clone().iter().cloned() { if !(match c.ident_span.clone() {
    Some(s) => ((s.file.clone().as_str() == "".to_string().as_str()) && (s.start.clone() == s.end.clone())),
    None => false,
}) { __all = false; break; } } __all });
if is_pair {
                        {
                            let first_child = match n.children.clone().first().cloned() {
    Some(c) => if (c.inferred.clone() != None) {
                                render_node_type(resolved_type_or_error(c.clone()), target.clone(), shared_types.clone(), source_index.clone())
} else {
                                render_node_type(c.clone(), target.clone(), shared_types.clone(), source_index.clone())
},
    None => "_".to_string(),
};
let second_child = match n.children.clone().get(1 as usize).cloned() {
    Some(c) => if (c.inferred.clone() != None) {
                                render_node_type(resolved_type_or_error(c.clone()), target.clone(), shared_types.clone(), source_index.clone())
} else {
                                render_node_type(c.clone(), target.clone(), shared_types.clone(), source_index.clone())
},
    None => "_".to_string(),
};
let tuple_str = render_tuple_parts(Rc::new(vec![first_child, second_child]), target.clone());
return tuple_str
}
}
if (n.ident_span.clone() != None) {
                        {
                            let snake = to_snake(n.name.clone());
let has_template = match container_to_algebra_name(snake.clone()) {
    Some(_) => true,
    None => false,
};
if has_template {
                                {
                                    let base = if (snake.clone().as_str() == "map".to_string().as_str()) {
                                        emit_map_type("_".to_string(), "_".to_string(), target.clone())
} else {
                                        emit_container(snake.clone(), "_".to_string(), target.clone())
};
let conj_container_str = if shared.clone() {
                                        wrap_shared_type(target.clone(), base.clone())
} else {
                                        base.clone()
};
return conj_container_str
}
}
let base = coerce_primitive_type(target.clone(), n.name.clone());
let conj_named_str = if shared.clone() {
                                wrap_shared_type(target.clone(), base.clone())
} else {
                                base.clone()
};
return conj_named_str
}
}
let parts = Rc::new({ let mut __result = Vec::new(); for child in n.children.clone().iter().cloned() { __result.push(render_node_type(resolved_type_or_error(child.clone()), target.clone(), shared_types.clone(), source_index.clone())); } __result });
let anon_str = render_tuple_parts(parts, target.clone());
return anon_str
}
}
if ((n.children.clone().len() as i64) == 0) {
                {
                    let bare_is_map = (is_container_type(n.name.clone()) && (to_snake(n.name.clone()).as_str() == "map".to_string().as_str()));
let bare_is_collection = (is_container_type(n.name.clone()) && !bare_is_map.clone());
let has_container_template = match container_to_algebra_name(to_snake(n.name.clone())) {
    Some(_) => true,
    None => false,
};
let param_count = (n.params.clone().len() as i64);
let base = if bare_is_map.clone() {
                        emit_map_type("_".to_string(), "_".to_string(), target.clone())
} else {
                        if bare_is_collection {
                            emit_container(to_snake(n.name.clone()), "_".to_string(), target.clone())
} else {
                            if (has_container_template && (param_count == 1)) {
                                {
                                    let inner = match n.params.clone().first().cloned() {
    Some(p) => render_node_type(param_node_type_expr(p.clone()), target.clone(), shared_types.clone(), source_index.clone()),
    None => "_".to_string(),
};
emit_container(to_snake(n.name.clone()), inner, target.clone())
}
} else {
                                if (n.name.clone().as_str() == tuple_type_name().as_str()) {
                                    render_tuple_parts(Rc::new(vec![]), target.clone())
} else {
                                    coerce_primitive_type(target.clone(), n.name.clone())
}
}
}
};
let bare_str = if shared.clone() {
                        wrap_shared_type(target.clone(), base.clone())
} else {
                        base.clone()
};
return bare_str
}
}
let is_map = node_is_keyed_collection(n.clone());
if is_map {
                {
                    let k = match n.children.clone().first().cloned() {
    Some(kn) => render_node_type(child_type_node(kn.clone()), target.clone(), shared_types.clone(), source_index.clone()),
    None => "_".to_string(),
};
let v = match n.children.clone().get(1 as usize).cloned() {
    Some(vn) => render_node_type(child_type_node(vn.clone()), target.clone(), shared_types.clone(), source_index.clone()),
    None => "_".to_string(),
};
let base = emit_map_type(k, v, target.clone());
let map_str = if shared.clone() {
                        wrap_shared_type(target.clone(), base.clone())
} else {
                        base.clone()
};
return map_str
}
}
if ((n.children.clone().len() as i64) == 1) {
                {
                    let child_str = match n.children.clone().first().cloned() {
    Some(child) => render_node_type(child_type_node(child.clone()), target.clone(), shared_types.clone(), source_index.clone()),
    None => "_".to_string(),
};
let is_container = node_is_collection(n.clone());
let base = if is_container {
                        emit_container(to_snake(n.name.clone()), child_str, target.clone())
} else {
                        {
                            let type_base = coerce_primitive_type(target.clone(), n.name.clone());
match target.clone() {
    RenderTarget::Python => v2_rt::concat(v2_rt::concat(v2_rt::concat(type_base.clone(), "[".to_string()), child_str), "]".to_string()),
    _ => v2_rt::concat(v2_rt::concat(v2_rt::concat(type_base.clone(), "<".to_string()), child_str), ">".to_string()),
}
}
};
let single_str = if shared.clone() {
                        wrap_shared_type(target.clone(), base.clone())
} else {
                        base.clone()
};
return single_str
}
}
let child_strs = Rc::new({ let mut __result = Vec::new(); for c in n.children.clone().iter().cloned() { __result.push(render_node_type(child_type_node(c.clone()), target.clone(), shared_types.clone(), source_index.clone())); } __result });
if (n.name.clone().as_str() == tuple_type_name().as_str()) {
                {
                    let multi_tuple_str = render_tuple_parts(child_strs.clone(), target.clone());
return multi_tuple_str
}
}
let type_base = coerce_primitive_type(target.clone(), n.name.clone());
let args_joined = child_strs.clone().join(&", ".to_string());
let base = match target.clone() {
    RenderTarget::Python => v2_rt::concat(v2_rt::concat(v2_rt::concat(type_base.clone(), "[".to_string()), args_joined), "]".to_string()),
    _ => v2_rt::concat(v2_rt::concat(v2_rt::concat(type_base.clone(), "<".to_string()), args_joined), ">".to_string()),
};
if shared.clone() {
                wrap_shared_type(target.clone(), base.clone())
} else {
                base.clone()
}
}
    })
}

pub fn render_tuple_parts(parts: Rc<Vec<String>>, target: RenderTarget) -> String {
    if ((parts.clone().len() as i64) > 0) {
        {
            let joined = parts.clone().join(&", ".to_string());
match target {
    RenderTarget::Go => if ((parts.clone().len() as i64) == 2) {
                match parts.clone().first().cloned() {
    Some(first_part) => match parts.clone().get(1 as usize).cloned() {
    Some(second_part) => v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("struct{ First ".to_string(), first_part.clone()), "; Second ".to_string()), second_part.clone()), " }".to_string()),
    None => v2_rt::concat(v2_rt::concat("struct{ ".to_string(), parts.clone().join(&"; ".to_string())), " }".to_string()),
},
    None => v2_rt::concat(v2_rt::concat("struct{ ".to_string(), parts.clone().join(&"; ".to_string())), " }".to_string()),
}
} else {
                v2_rt::concat(v2_rt::concat("struct{ ".to_string(), parts.clone().join(&"; ".to_string())), " }".to_string())
},
    RenderTarget::Python => v2_rt::concat(v2_rt::concat("Tuple[".to_string(), joined), "]".to_string()),
    _ => v2_rt::concat(v2_rt::concat("(".to_string(), joined), ")".to_string()),
}
}
} else {
        match target {
    RenderTarget::Python => "Tuple".to_string(),
    RenderTarget::Go => "struct{}".to_string(),
    _ => "()".to_string(),
}
}
}

